import{_ as t,o as p,c as a,a2 as e}from"./chunks/framework.BXzK3EA4.js";const o="/assets/62860ebd9862bade.6qBecj7k.png",r="/assets/3e73d1973531eeb0.DrRxMxgy.png",c="/assets/b85645ba5b65ff22.DRISMQqy.png",n="/assets/bd039a9f2cd745a1.EX_kcVtq.png",i="/assets/f82bd7aa1c05c792.D0WQm8o4.png",l="/assets/621e5f5fb0bba15a.ClMOsHl4.png",_="/assets/bac4ed1bd92e706c.C3B2BvjR.png",d="/assets/abbc42d164035c67.BVA8sprw.png",g="/assets/7be266c9ac96bba9.BnktXmeV.png",B=JSON.parse('{"title":"云原生备份使用操作","description":"","frontmatter":{"title":"云原生备份使用操作"},"headers":[],"relativePath":"ops-knowledge-base/cloud-native/backup-guide.md","filePath":"ops-knowledge-base/cloud-native/backup-guide.md","lastUpdated":1788259091000}'),m={name:"ops-knowledge-base/cloud-native/backup-guide.md"};function b(u,s,f,k,h,q){return p(),a("div",null,[...s[0]||(s[0]=[e('<p><strong>备份</strong>是用于捕捉硬盘在某一个时刻的状态，未来可以随时恢复到这个状态。 在某些时候，例如误操作或者应用逻辑的 bug，可能会导致业务数据的丢失，这时就需要通过备份功能，从历史备份点恢复数据。</p><p>备份须知</p><p>当你对正在运行的云服务器或者已经绑定的硬盘做在线备份时，需要注意以下几点：</p><ul><li>备份只能捕获在备份任务开始时已经写入磁盘的数据，不包括当时位于缓存内的数据。</li><li>为了保证数据的完整性，需要在创建备份前暂停所有文件的写操作，直到备份进入”捕获完成”的状态。也可停止云服务器或解绑硬盘后，进行离线备份。</li></ul><p>若是首次创建备份，需要先购买备份，购买时对应服务器的规格购买即可。</p><p><img src="'+o+'" alt=""></p><h2 id="一-创建备份" tabindex="-1">一．创建备份 <a class="header-anchor" href="#一-创建备份" aria-label="Permalink to &quot;一．创建备份&quot;">​</a></h2><p>1.输入备份名称，点击<strong>提交</strong>，开始创建。创建成功后，生成备份记录，如下图所示。</p><p><img src="'+r+'" alt=""></p><p>二．备份回滚</p><p>1.选择要回滚的备份点，点击确认，开始回滚并应用备份，待回滚完成即可。</p><p><img src="'+c+'" alt=""></p><p><img src="'+n+'" alt=""></p><h2 id="三-删除备份" tabindex="-1">三．删除备份 <a class="header-anchor" href="#三-删除备份" aria-label="Permalink to &quot;三．删除备份&quot;">​</a></h2><p>您可以删除整个备份链，也可以删除某一个备份点。</p><p>1.若是删除全量备份点</p><p><img src="'+i+'" alt=""></p><p>点击确认，删除整条备份链。</p><p><img src="'+l+'" alt=""></p><p>2.若是删除增量备份点</p><p>单击<strong>确认</strong>，删除该增量备份点及其所有子节点（若有）。</p><p><img src="'+_+'" alt=""></p><p>四.升级备份</p><p>如果备份的容量不够，可以对备份容量大小进行升级</p><p><img src="'+d+'" alt=""></p><p>对备份的容量大小进行升级</p><p><img src="'+g+'" alt=""></p>',27)])])}const v=t(m,[["render",b]]);export{B as __pageData,v as default};
